import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import PropertyCard from '../components/PropertyCard';
import HeroSearch from '../components/HeroSearch';
import EnquiryModal from '../components/EnquiryModal';
import { getProperties } from '../services/api';
import {
  ShieldCheck, UserCheck, Percent, PhoneCall,
  Building2, Home, TreePine, Store, Landmark, BedDouble,
  ArrowRight, Sparkles, TrendingUp
} from 'lucide-react';
import styles from './HomePage.module.css';

/* ── Value Propositions ───────────────────────────────────────── */
const VALUE_PROPS = [
  {
    icon: ShieldCheck,
    title: '100% Verified Properties',
    desc: 'Every home physically verified & documentation checked.',
  },
  {
    icon: UserCheck,
    title: 'Direct Owner Connect',
    desc: 'Talk directly with genuine owners and trusted builders.',
  },
  {
    icon: Percent,
    title: 'Zero Brokerage Options',
    desc: 'Thousands of verified listings with 0% brokerage fees.',
  },
  {
    icon: PhoneCall,
    title: 'Instant Support & Visit',
    desc: 'Schedule on-site visits and get free expert assistance.',
  },
];

/* ── Categories ───────────────────────────────────────────────── */
const CATEGORIES = [
  { id: 'apartment',   title: 'Apartments',        icon: Building2, count: '12,400+ Homes' },
  { id: 'villa',       title: 'Luxury Villas',     icon: Home,      count: '3,800+ Villas' },
  { id: 'plot',        title: 'Plots & Land',      icon: TreePine,  count: '5,200+ Plots'  },
  { id: 'commercial',  title: 'Commercial',        icon: Store,     count: '2,900+ Spaces' },
  { id: 'independent', title: 'Independent House', icon: Landmark,  count: '4,100+ Houses' },
  { id: 'pg',          title: 'PG & Co-Living',    icon: BedDouble, count: '1,600+ Rooms'  },
];

/* ── Top Cities ───────────────────────────────────────────────── */
const CITIES = [
  { name: 'Bengaluru', count: '14,200+ Properties', image: 'https://images.unsplash.com/photo-1625134673337-519d4d10b313?w=600&q=80' },
  { name: 'Mumbai',    count: '11,500+ Properties', image: 'https://images.unsplash.com/photo-1570168007204-dfb528c6958f?w=600&q=80' },
  { name: 'Chennai',   count: '8,900+ Properties',  image: 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=600&q=80' },
  { name: 'Hyderabad', count: '9,400+ Properties',  image: 'https://images.unsplash.com/photo-1584443483978-5ec6c0ba7649?w=600&q=80' },
  { name: 'Pune',      count: '6,700+ Properties',  image: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600&q=80' },
  { name: 'Delhi NCR', count: '15,100+ Properties', image: 'https://images.unsplash.com/photo-1587474260584-136574528ed5?w=600&q=80' },
];

export default function HomePage() {
  const navigate = useNavigate();
  const [properties, setProperties]   = useState([]);
  const [loading, setLoading]         = useState(true);
  const [enquiryProp, setEnquiryProp] = useState(null);
  const [filterTab, setFilterTab]     = useState('all');

  useEffect(() => {
    getProperties({ limit: 8 })
      .then(({ data }) => setProperties(data.properties || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  // Filter properties client-side based on quick pill
  const filteredProperties = useMemo(() => {
    if (filterTab === 'all') return properties;
    if (filterTab === 'buy')  return properties.filter(p => (p.listingType || '').toLowerCase() === 'sell');
    if (filterTab === 'rent') return properties.filter(p => (p.listingType || '').toLowerCase() === 'rent');
    if (filterTab === 'commercial') return properties.filter(p => (p.buildingType || '').toLowerCase() === 'commercial');
    return properties;
  }, [properties, filterTab]);

  return (
    <div className={styles.homeWrap}>

      {/* ── 1. Hero Search (Homes247 layout, Forest Green & Light Yellow) ── */}
      <HeroSearch />

      {/* ── 2. Trust Value Props Strip ───────────────────────── */}
      <section className={styles.valuePropsSection}>
        <div className={`container ${styles.valuePropsGrid}`}>
          {VALUE_PROPS.map((v, i) => (
            <div key={i} className={styles.valueCard}>
              <div className={styles.valueIconWrap}>
                <v.icon size={22} className={styles.valueIcon} />
              </div>
              <div className={styles.valueText}>
                <h3 className={styles.valueTitle}>{v.title}</h3>
                <p className={styles.valueDesc}>{v.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* ── 3. Explore By Category ────────────────────────────── */}
      <section className={`container ${styles.section}`}>
        <div className={styles.sectionHeader}>
          <div>
            <div className={styles.eyebrow}>
              <Sparkles size={13} className={styles.eyebrowIcon} />
              <span>EXPLORE CATEGORIES</span>
            </div>
            <h2 className={styles.sectionTitle}>Browse Properties by Type</h2>
            <p className={styles.sectionSub}>Find the perfect match for your lifestyle or investment goals</p>
          </div>
        </div>

        <div className={styles.categoriesGrid}>
          {CATEGORIES.map(cat => {
            const Icon = cat.icon;
            return (
              <button
                key={cat.id}
                className={styles.categoryCard}
                onClick={() => navigate(`/search?propertyType=${cat.id}`)}
              >
                <div className={styles.catIconWrap}>
                  <Icon size={24} className={styles.catIcon} />
                </div>
                <div className={styles.catInfo}>
                  <div className={styles.catTitle}>{cat.title}</div>
                  <div className={styles.catCount}>{cat.count}</div>
                </div>
                <div className={styles.catArrow}>→</div>
              </button>
            );
          })}
        </div>
      </section>

      {/* ── 4. Popular / Curated Properties ──────────────────── */}
      <section className={`container ${styles.section}`}>
        <div className={styles.propertiesHeaderRow}>
          <div>
            <div className={styles.eyebrow}>
              <TrendingUp size={13} className={styles.eyebrowIcon} />
              <span>HANDPICKED FOR YOU</span>
            </div>
            <h2 className={styles.sectionTitle}>Popular Properties</h2>
            <p className={styles.sectionSub}>Curated verified homes in prime residential hubs</p>
          </div>

          {/* Quick filter pills */}
          <div className={styles.filterPills}>
            {[
              { id: 'all',        label: 'All Homes'  },
              { id: 'buy',        label: 'For Sale'   },
              { id: 'rent',       label: 'For Rent'   },
              { id: 'commercial', label: 'Commercial' },
            ].map(tab => (
              <button
                key={tab.id}
                className={`${styles.filterPill} ${filterTab === tab.id ? styles.filterPillActive : ''}`}
                onClick={() => setFilterTab(tab.id)}
              >
                {tab.label}
              </button>
            ))}
            <button className={styles.seeAllBtn} onClick={() => navigate('/search')}>
              See All (500+) →
            </button>
          </div>
        </div>

        {loading ? (
          <div className={styles.loadingGrid}>
            {[1, 2, 3, 4].map(n => (
              <div key={n} className={styles.skeletonCard} />
            ))}
          </div>
        ) : filteredProperties.length === 0 ? (
          <div className={styles.emptyState}>
            <div className={styles.emptyIcon}>🏠</div>
            <h3 className={styles.emptyTitle}>No Properties Found In This Filter</h3>
            <p className={styles.emptySub}>Browse all our active verified listings across top cities.</p>
            <button className={styles.emptyBtn} onClick={() => navigate('/search')}>
              Explore All Listings
            </button>
          </div>
        ) : (
          <div className={styles.propertiesGrid}>
            {filteredProperties.map(p => (
              <PropertyCard key={p.id || p._id} property={p} onEnquire={setEnquiryProp} />
            ))}
          </div>
        )}
      </section>

      {/* ── 5. Commercial Spotlight Banner (Forest Green & Gold) ── */}
      <section className={`container ${styles.section}`}>
        <div className={styles.commercialCard}>
          <div className={styles.commercialLeft}>
            <div className={styles.commercialTag}>
              <Sparkles size={12} />
              <span>INSTITUTIONAL ASSETS &bull; HIGH CAP RATE</span>
            </div>
            <h2 className={styles.commercialTitle}>Commercial Real Estate Spotlight</h2>
            <p className={styles.commercialBody}>
              Pre-leased Grade-A corporate parks, retail high-streets & modern co-working towers
              with guaranteed 9-year long lock-ins and high rental yields.
            </p>
            <div className={styles.commercialActions}>
              <button
                className={styles.commercialBtn}
                onClick={() => navigate('/search?buildingType=Commercial')}
              >
                <span>Explore Commercial Spaces</span>
                <ArrowRight size={16} />
              </button>
            </div>
          </div>

          <div className={styles.commercialMetrics}>
            {[
              { value: '8.5 – 12%', label: 'Average Annual Rental Yield' },
              { value: '9+ Years',  label: 'Corporate Tenant Lock-in'  },
              { value: 'Grade-A',   label: 'Pre-leased Bluechip Assets' },
            ].map((m, i) => (
              <div key={i} className={styles.metricItem}>
                <div className={styles.metricVal}>{m.value}</div>
                <div className={styles.metricLbl}>{m.label}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ── 6. Explore Top Cities Grid ────────────────────────── */}
      <section className={`container ${styles.section}`}>
        <div className={styles.sectionHeader}>
          <div>
            <div className={styles.eyebrow}>
              <span>URBAN HUBS</span>
            </div>
            <h2 className={styles.sectionTitle}>Explore Properties by City</h2>
            <p className={styles.sectionSub}>Top metropolitan cities with highest rental yield and capital appreciation</p>
          </div>
        </div>

        <div className={styles.citiesGrid}>
          {CITIES.map(c => (
            <button
              key={c.name}
              className={styles.cityCard}
              onClick={() => navigate(`/search?city=${c.name}`)}
              style={{ backgroundImage: `url(${c.image})` }}
            >
              <div className={styles.cityGradient} />
              <div className={styles.cityContent}>
                <span className={styles.cityCountBadge}>{c.count}</span>
                <h3 className={styles.cityName}>{c.name}</h3>
                <span className={styles.cityAction}>View Listings &rarr;</span>
              </div>
            </button>
          ))}
        </div>
      </section>

      {/* ── 7. Post Property Banner ──────────────────────────── */}
      <section className={`container ${styles.section}`}>
        <div className={styles.postBanner}>
          <div className={styles.postBannerContent}>
            <span className={styles.postBannerEyebrow}>FOR OWNERS &amp; BUILDERS</span>
            <h2 className={styles.postBannerTitle}>List Your Property on ProBridge for Free</h2>
            <p className={styles.postBannerSub}>
              Connect with thousands of genuine buyers and verified tenants without paying any brokerage fees.
            </p>
            <div className={styles.postBannerPerks}>
              <span>✓ 100% Free Listing</span>
              <span>✓ Direct Inquiries on Phone</span>
              <span>✓ Dedicated Relationship Manager</span>
            </div>
          </div>
          <button className={styles.postBannerBtn} onClick={() => navigate('/post-property')}>
            Post Property Free &rarr;
          </button>
        </div>
      </section>

      {/* Enquiry Modal */}
      {enquiryProp && (
        <EnquiryModal property={enquiryProp} onClose={() => setEnquiryProp(null)} />
      )}
    </div>
  );
}
